function OverseaClubCatCarRankClubNode:SetRewardTipsShow(isCurrent)
    KTool.SetActive(self.RewardReceiveTips.gameObject,isCurrent)
    if isCurrent then
        ---@type OverseaClubCatCarMgr
        local mgr = import("Game.UI.Club.CatCar.OverseaClubCatCarMgr"):GetInstance()
        local times = 0
        times = checkNumber(mgr.Server.dojo.totalSubmitDiceTimes)
        local needCount = ClubUtils.GetParamValue(ClubUtils.ParamsId.Rank_Reward_Min_Count)
        if times > needCount then
            times = needCount
        end
        CfUtils.FillText(self.TextDesc2,localize("领取排名奖励需在该社团参与猫车_Time1_次（_Time2_/_Time3_)",{_Time1_ = needCount,_Time2_ = times,_Time3_ = needCount}))
    end
end

function OverseaClubCatCarRankClubNode:RefreshReward()
    if self.rewardNodeEnv then
        local ranking = self.data.myRank.ranking
        local hasRank = ranking ~= 0
        local rewards = hasRank and ClubUtils.GetCatCarRankReward(ranking) or {}
        self.rewardNodeEnv:Refresh(rewards, hasRank, nil, function()
            CfUtils.DialogOpen(Constants.UITypeIds.UIClubBossRankRewardDialog, {autoId = AutoIds.IdSetting6296, voName = 'ClubCatCarRankRewardVo'})
        end)
    end
end

